//! Raw native named presence and own descriptors preserve actual attributes.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_reflect_get_native_own_data_ignores_receiver_properties_and_hooks(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,r={},hits=0;d.first='native';d['x\ud800']='raw\udfff';for(var key of ['first','x\ud800'])Object.defineProperty(r,key,{get:function(){hits++;throw 'receiver getter';}});for(var receiver of [r,null,undefined,7,true,'primitive']){if(Reflect.get(d,'first',receiver)!=='native'||Reflect.get(d,'x\ud800',receiver)!=='raw\udfff')throw 'native own data ignores receiver';}var proxy=new Proxy({}, {get:function(){hits++;throw 'proxy receiver get';}});if(Reflect.get(d,'first',proxy)!=='native'||hits)throw 'own read does not consult receiver';"#);}

#[test]
fn dataset_reflect_get_prototype_scalar_raw_getters_receive_actual_receiver(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,r={mark:17},seen=[];for(var key of ['probe','x\ud800'])Object.defineProperty(DOMStringMap.prototype,key,{get:function(){'use strict';seen.push(this);return this.mark;},configurable:true});if(Reflect.get(d,'probe',r)!==17||Reflect.get(d,'x\ud800',r)!==17||seen[0]!==r||seen[1]!==r)throw 'actual prototype receiver';d.probe='native';d['x\ud800']='own';if(Reflect.get(d,'probe',r)!=='native'||Reflect.get(d,'x\ud800',r)!=='own'||seen.length!==2)throw 'native named data shadows prototype';delete d.probe;delete d['x\ud800'];if(Reflect.get(d,'probe',r)!==17||Reflect.get(d,'x\ud800',r)!==17||seen.length!==4)throw 'live native deletion restores prototype';"#);}

#[test]
fn dataset_reflect_get_symbol_own_and_inherited_accessors_preserve_receiver_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,a=Symbol(),b=Symbol(),r={},value={},seen=0;d[a]=value;if(Reflect.get(d,a,r)!==value)throw 'own Symbol data ignores receiver';Object.defineProperty(d,a,{get:function(){if(this!==r)throw 'own Symbol getter receiver';seen++;return value;},configurable:true});Object.defineProperty(DOMStringMap.prototype,b,{get:function(){if(this!==r)throw 'inherited Symbol getter receiver';seen++;return 9;},configurable:true});if(Reflect.get(d,a,r)!==value||Reflect.get(d,b,r)!==9||seen!==2||Reflect.get(d,Symbol(),r)!==undefined)throw 'native Symbol ordinary lookup';"#);}

#[test]
fn dataset_reflect_get_key_conversion_once_observes_mutation_and_abrupt_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,r={},order='',key={toString:function(){order+='K';d['x\ud800']='after';return 'x\ud800';}};if(Reflect.get(d,key,r)!=='after'||order!=='K')throw 'key conversion before native observation';var marker={},caught;try{Reflect.get(d,{toString:function(){d.side='effect';throw marker;}},r);}catch(e){caught=e;}if(caught!==marker||d.side!=='effect')throw 'key abrupt identity and authored effects';var get=Reflect.get;if(get.call({toString:function(){throw 'unused method this';}},d,'side',r)!=='effect')throw 'borrowed get';"#);}

#[test]
fn dataset_reflect_get_primitive_and_explicit_undefined_receiver_preserved_for_strict_getter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset;Object.defineProperty(DOMStringMap.prototype,'probe',{get:function(){'use strict';return this;},configurable:true});for(var receiver of [null,undefined,7,true,'primitive'])if(Reflect.get(d,'probe',receiver)!==receiver)throw 'strict primitive receiver';if(Reflect.get(d,'probe')!==d||Reflect.get(d,'probe',undefined)!==undefined)throw 'omitted versus explicit undefined';var marker={},caught;Object.defineProperty(DOMStringMap.prototype,'abrupt',{get:function(){throw marker;},configurable:true});try{Reflect.get(d,'abrupt',{});}catch(e){caught=e;}if(caught!==marker)throw 'prototype abrupt identity';"#);}

#[test]
fn dataset_reflect_get_html_svg_actual_named_and_prototype_paths_remain_distinct(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset,r={name:'receiver'},hits=0;d['x\ud800Name']='native';Object.defineProperty(DOMStringMap.prototype,'x\ud800Name',{get:function(){hits++;return this.name;},configurable:true});var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});if(Reflect.get(d,'x\ud800Name',r)!=='native'||hits||watch.takeRecords().length)throw 'actual HTML SVG native data';delete d['x\ud800Name'];watch.takeRecords();if(Reflect.get(d,'x\ud800Name',r)!=='receiver'||hits!==1||watch.takeRecords().length)throw 'actual prototype after deletion';delete DOMStringMap.prototype['x\ud800Name'];}"#);}

#[test]
fn dataset_reflect_get_native_copy_work_deadline_refusals_preserve_dom_and_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','{}');var watch=new MutationObserver(function(){{}});watch.observe(n,{{attributes:true}});"#,"x".repeat(16000)));let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute(r#"Reflect.get(data,'x\ud800',{});"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(["string work","DOM work","computation time"][mode]),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.execution_deadline=None;run(&mut d,&mut f,&mut p,r#"if(Reflect.get(data,'x\ud800',{}).length!==16000||watch.takeRecords().length)throw 'read refusal recovery';"#);}}
#[test]
fn dataset_reflect_get_other_native_families_preserve_distinct_receiver_refusal(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;data.ready='native';if(Reflect.get(data,'ready',{})!=='native')throw 'dataset scope';"#);let before=format!("{:?}",d.nodes);p.begin_job();let error=p.runtime.execute("Reflect.get(n,'id',{});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("different receiver on a native target is not implemented"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);run(&mut d,&mut f,&mut p,r#"if(Reflect.get(data,'ready',{})!=='native'||n.id!=='target')throw 'scoped native recovery';"#);}
